contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint fund) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (fund)); require(fund <= 1000000000000000000000000000000);
        require(address(this).balance >= fund);
        // fund c through its receive() via Command (empty calldata, self-target)
        c.Command{value: fund}(address(c), ""); if (__ESBMC_reverted()) return;
        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(!reverted && address(c).balance == 0);
    }
    receive() external payable {}
}

